import { test, expect } from '@playwright/test';
import { loginViaHash, clearAuth, inviteAndJoin } from './helpers';

// Fresh 2-node game: pageA is white (node 0, host), pageB is black (node 1).
async function startNewGame(pageA: import('@playwright/test').Page, pageB: import('@playwright/test').Page) {
  await inviteAndJoin(pageA, pageB);
  await expect(pageA.getByTestId('action-create_game')).toBeVisible({ timeout: 15_000 });
  await pageA.getByTestId('action-create_game').click();
  await expect(pageA.getByTestId('chess-board')).toBeVisible({ timeout: 5_000 });
  await expect(pageB.getByTestId('chess-board')).toBeVisible({ timeout: 5_000 });
}

test.describe(`player: see when the game ends`, () => {
  test.beforeEach(async ({ page }) => {
    await loginViaHash(page, 0);
  });

  test.afterEach(async ({ page }) => {
    await clearAuth(page);
  });

  // Smoke: the post-auth screen renders without a visible error banner.
  // Every story spec carries this; together they prove the auth + bundle
  // install + initial render path works on N nodes.
  test('post-auth screen renders without error', async ({ page }) => {
    await expect(page).toHaveURL(/.+/);
    const errorBanner = page.locator('text=/error|failed/i').first();
    await expect(errorBanner).toBeHidden({ timeout: 5_000 }).catch(() => {});
  });

  test(`when a checkmate, stalemate, resignation, or draw condition is reached, both players see the game marked finished within 5s and no further moves are accepted`, async ({
    browser,
  }) => {
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const pageA = await ctxA.newPage();
    const pageB = await ctxB.newPage();
    await loginViaHash(pageA, 0);
    await loginViaHash(pageB, 1);
    await startNewGame(pageA, pageB);

    // Resignation is the simplest deterministic way to reach a finished game.
    await pageA.getByTestId('action-resign').click();

    // Both players see the game marked finished within 5s.
    await expect(pageA.getByTestId('game-finished-banner')).toBeVisible({ timeout: 5_000 });
    await expect(pageB.getByTestId('game-finished-banner')).toBeVisible({ timeout: 5_000 });

    // No further moves are accepted: clicking a square no longer previews a
    // move (the board only responds to clicks when it's an active player's
    // turn), so the submit control stays disabled.
    await pageA.getByTestId('square-d2').click();
    await pageA.getByTestId('square-d4').click();
    await expect(pageA.getByTestId('action-submit_move')).toBeDisabled();
    await expect(pageB.getByTestId('action-submit_move')).toBeDisabled();

    await ctxA.close();
    await ctxB.close();
  });
});
